import React, { useState } from "react";
import axios from "axios";
import { getFirestore, collection, addDoc } from "firebase/firestore";
import { app } from "../../../firebaseConfig"; // Firebase setup

const firestore = getFirestore(app);

const ImageUploader = () => {
  const [images, setImages] = useState([]);
  const [uploadedData, setUploadedData] = useState({
    allPhoto: [],
  });

  const handleUpload = async () => {
    if (images.length < 3) {
      alert("Please select at least 3 images (1 for slider, 1 for bigPhoto, and others for allPhoto).");
      return;
    }

    const formData = new FormData();
    images.forEach((img) => formData.append("images", img));

    try {
      const { data } = await axios.post("http://localhost:5000/upload", formData);

      const structuredData = {
        slider: data.urls[0], // First image as slider
        bigPhoto: data.urls[1], // Second image as big photo
        allPhoto: data.urls, // Store all uploaded images
      };

      setUploadedData(structuredData);

      // Store in Firebase Firestore
      await addDoc(collection(firestore, "uploads-images"), {
        uploadedAt: new Date(),
        ...structuredData,
      });

      console.log("Images uploaded:", structuredData);
    } catch (error) {
      console.error("Upload failed", error);
    }
  };

  return (
    <div>
      <input type="file" multiple onChange={(e) => setImages(Array.from(e.target.files || []))} />
      <button onClick={handleUpload}>Upload</button>

      {uploadedData.slider && <img src={uploadedData.slider} alt="Slider" width="200px" />}
      {uploadedData.bigPhoto && <img src={uploadedData.bigPhoto} alt="Big Photo" width="200px" />}
      {uploadedData.allPhoto.length > 0 && (
        <div>
          <h3>All Photos</h3>
          {uploadedData.allPhoto.map((url, index) => (
            <img key={index} src={url} alt={`AllPhoto-${index}`} width="150px" />
          ))}
        </div>
      )}
    </div>
  );
};

export default ImageUploader;
